import { Component, computed, input } from '@angular/core';

@Component({
  selector: 'app-user-card',
  template: `
    <article>
      <h2>{{ name() }}</h2>
      <p>{{ role() }} · {{ initials() }}</p>
    </article>
  `,
})
export class UserCard {
  readonly name = input.required<string>();
  readonly role = input('Member');

  readonly initials = computed(() =>
    this.name()
      .split(' ')
      .map((part) => part[0])
      .join(''),
  );
}

import { Component, signal } from '@angular/core';
import { UserCard } from '../user-card/user-card';

@Component({
  selector: 'app-team',
  imports: [UserCard],
  template: `
    <app-user-card name="Ada Lovelace" role="Founder" />
    <app-user-card [name]="second()" />
  `,
})
export class Team {
  readonly second = signal('Grace Hopper');
}

import { Component, input, output } from '@angular/core';

@Component({
  selector: 'app-task-item',
  template: `
    <li>
      {{ title() }}
      <button (click)="remove.emit(id())">Remove</button>
    </li>
  `,
})
export class TaskItem {
  readonly id = input.required<number>();
  readonly title = input.required<string>();
  readonly remove = output<number>();
}

import { Component, signal } from '@angular/core';
import { TaskItem } from '../task-item/task-item';

@Component({
  selector: 'app-task-list',
  imports: [TaskItem],
  template: `
    <ul>
      @for (task of tasks(); track task.id) {
        <app-task-item [id]="task.id" [title]="task.title" (remove)="removeTask($event)" />
      }
    </ul>
    <p>{{ tasks().length }} left</p>
  `,
})
export class TaskList {
  readonly tasks = signal([
    { id: 1, title: 'Buy milk' },
    { id: 2, title: 'Call Grace' },
  ]);

  removeTask(id: number): void {
    this.tasks.update((list) => list.filter((task) => task.id !== id));
    console.log(`removed task ${id}`);
  }
}

import { Component, model } from '@angular/core';

@Component({
  selector: 'app-toggle',
  template: `
    <button role="switch" [attr.aria-checked]="checked()" (click)="checked.update((on) => !on)">
      {{ checked() ? 'On' : 'Off' }}
    </button>
  `,
})
export class Toggle {
  readonly checked = model(false);
}
